content.text:
        _fail("capacity")

    evs = _list(d["events"])
    if len(evs) > MAX_EVENTS:
        _fail("too many events")
    norm = []
    total = 0
    prev_t = -1
    for e in evs:
        e = _dict(e)
        _exact(e, ("t", "peer", "auth", "egress", "wire_hex"))
        t = _int(e["t"])
        if t < 0 or t > MAX_T:
            _fail("t range")
        if t < prev_t:
            _fail("descending t")
        prev_t = t
        pid = _str(e["peer"])
        mode = peer_mode.get(pid)
        if mode is None:
            _fail("unknown peer")
        auth = e["auth"]
        if auth is not None:
            auth = _str(auth)
            if auth not in acct_ids:
                _fail("unknown account")
            if mode == "relay":
                _fail("relay auth must be null")
        eg = _str(e["egress"])
        if eg != "internal" and eg != "external":
            _fail("egress")
        hx = _str(e["wire_hex"])
        if len(hx) > MAX_HEXLEN:
            _fail("wire_hex length")
        total += len(hx) >> 1
        norm.append((t, pid, auth, eg, hx))
    if total > MAX_TOTAL_WIRE:
        _fail("wire byte budget")

    return {
        "alias_owner": alias_owner,
        "defaults": defaults,
        "peer_mode": peer_mode,
        "peer_accounts": peer_accounts,
        "ttl": ttl,
        "cap": cap,
        "events": norm,
    }


