def apply_policy(req, pid, auth, egress, ctx):
    mode = ctx["peer_mode"][pid]
    alias_owner = ctx["alias_owner"]
    pai = req["pai"]
    ppi = req["ppi"]
    privacy = req["privacy"]

    if mode == "access":
        if auth is None:
            raise Reject("auth")
        acct = auth
        if ppi is not None:
            for uri in ppi:
                if alias_owner.get(uri) != acct:
                    raise Reject("identity")
            asserted = ppi
            selected = ppi[0]
        else:
            selected = ctx["defaults"][acct]
            asserted = [selected]
    else:
        if ppi is not None or pai is None:
            raise Reject("identity")
        acct = None
        for uri in pai:
            owner = alias_owner.get(uri)
            if owner is None:
                raise Reject("identity")
            if acct is None:
                acct = owner
            elif owner != acct:
                raise Reject("identity")
        if acct not in ctx["peer_accounts"][pid]:
            raise Reject("identity")
        asserted = pai
        selected = pai[0]

    from_uri = req["from_uri"]
    if from_uri == ANON:
        if privacy != "id":
            raise Reject("identity")
    elif alias_owner.get(from_uri) != acct:
        raise Reject("identity")

    if privacy == "id":
        out_from = ANON
    else:
        out_from = selected
    if egress == "external" and privacy != "none":
        out_pai = []
    else:
        out_pai = list(asserted)

    req["account"] = acct
    req["selected"] = selected
    req["asserted"] = asserted
    req["out_from"] = out_from
    req["out_pai"] = out_pai
    return req


def record(index, decision, first, req):
    return {
        "index": index,
        "decision": decision,
